"""
Script de diagnóstico: analisa o blob binário da coluna Inventory
(formato ItemDbByte = 16, INVENTORY_SIZE = 108) e imprime, byte a byte,
apenas os slots que não estão vazios.

Uso:
    1. Cole o hex completo do dump na variável HEX_DUMP abaixo
       (ou passe via arquivo/stdin, veja o final do script).
    2. Rode: python dump_inventory_slots.py
"""

ITEM_DB_BYTE = 16
INVENTORY_SIZE = 108


def dump_inventory_slots(hex_or_binary: str, item_db_byte: int = ITEM_DB_BYTE, inventory_size: int = INVENTORY_SIZE):
    # Aceita tanto string hex quanto bytes puros
    if isinstance(hex_or_binary, str):
        clean = hex_or_binary.strip().replace(" ", "").replace("\n", "").replace("\r", "").replace("\t", "")

        # Remove prefixo "0x"/"0X" no início, se presente (comum ao copiar de SSMS/debugger)
        if clean.lower().startswith("0x"):
            clean = clean[2:]

        try:
            binary = bytes.fromhex(clean)
        except ValueError as e:
            # Mostra a vizinhança do caractere problemático para facilitar o diagnóstico
            msg = str(e)
            print(f"Erro ao converter hex: {msg}")
            print(f"Primeiros 40 caracteres do hex recebido: {clean[:40]!r}")
            print(f"Tamanho total da string: {len(clean)} caracteres")
            raise ValueError("String fornecida não é um hex válido. Verifique se não há prefixo '0x', espaços ou caracteres extras.")
    else:
        binary = hex_or_binary

    expected_len = item_db_byte * inventory_size
    if len(binary) != expected_len:
        print(f"AVISO: tamanho não bate. Esperado {expected_len} bytes, recebido {len(binary)} bytes.\n")

    found_any = False

    for n in range(inventory_size):
        offset = n * item_db_byte
        slot = binary[offset:offset + item_db_byte]

        if len(slot) < item_db_byte:
            break

        byte0 = slot[0]
        byte7 = slot[7]
        byte9 = slot[9]

        is_empty = (byte0 == 0xFF and (byte7 & 0x80) == 0x80 and (byte9 & 0xF0) == 0xF0)

        if not is_empty:
            found_any = True
            hex_bytes = " ".join(f"{b:02X}" for b in slot)
            print(f"Slot {n:3d}: {hex_bytes}")

    if not found_any:
        print("Nenhum slot ocupado encontrado (todos os slots parecem vazios pelo critério atual).")


if __name__ == "__main__":
    # ---- Opção 1: colar o hex direto aqui ----
    HEX_DUMP = ""

    if HEX_DUMP != "COLE_AQUI_O_HEX_COMPLETO":
        dump_inventory_slots(HEX_DUMP)
    else:
        # ---- Opção 2: ler de um arquivo texto (uma linha só com o hex) ----
        import sys
        if len(sys.argv) > 1:
            with open(sys.argv[1], "r", encoding="utf-8") as f:
                dump_inventory_slots(f.read())
        else:
            print("Nenhum hex definido. Edite HEX_DUMP no script ou rode:")
            print("    python dump_inventory_slots.py caminho_para_arquivo_com_hex.txt")